{
  "title": "facebook-page-scraper",
  "description": "Extract public information from Facebook pages. Get page info, categories, number of likes, address, phone, email, services and rating (whatever is available for the given page). If you need any guidance, just <a href='https://blog.apify.com/how-to-scrape-facebook-pages-posts-comments-photos-and-more/' target='_blank' rel='noopener'>follow this tutorial</a>.",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "startUrls": {
      "title": "Start urls",
      "description": "Provide urls of Facebook pages you want to get information from. Only works on facebook pages, not personal profiles (not even public ones).",
      "default": [],
      "prefill": [
        {
          "url": "https://www.facebook.com/copperkettleyqr/"
        }
      ],
      "example": [
        {
          "url": "https://www.facebook.com/copperkettleyqr/"
        },
        {
          "url": "https://www.facebook.com/HiltonGardenInnMontrealAirport/"
        }
      ],
      "type": "array",
      "uniqueItems": true,
      "editor": "requestListSources"
    }
  },
  "required": [
    "startUrls"
  ]
}
